const upsertCameraState = `-- name: UpsertCameraState :exec
INSERT INTO streaming_camera_states (camera_id, health, viewers, codec, width, height, fps, reported_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, now())
ON CONFLICT (camera_id) DO UPDATE SET health = EXCLUDED.health, viewers = EXCLUDED.viewers, codec = EXCLUDED.codec,
    width = EXCLUDED.width, height = EXCLUDED.height, fps = EXCLUDED.fps, reported_at = EXCLUDED.reported_at
`

type UpsertCameraStateParams struct {
	CameraID uuid.UUID
	Health   string
	Viewers  int32
	Codec    *string
	Width    *int32
	Height   *int32
	Fps      *float64
}

func (q *Queries) UpsertCameraState(ctx context.Context, arg UpsertCameraStateParams) error {
	_, err := q.db.Exec(ctx, upsertCameraState,
		arg.CameraID,
		arg.Health,
		arg.Viewers,
		arg.Codec,
		arg.Width,
		arg.Height,
		arg.Fps,
	)
	return err
}
